735|      }
736|
737|      else
738|      {
739|         fprintf(stderr, "libpng error: %s, offset=%d",
740|             error_message, offset);
741|         fprintf(stderr, PNG_STRING_NEWLINE);
742|      }
743|   }
744|   else
745|#endif
746|   {
747|      fprintf(stderr, "libpng error: %s", error_message ? error_message :
748|         "undefined");
