6639|
6640|         pos = safecatn(message, sizeof message, pos, dp->output_colour_type);
6641|         pos = safecat(message, sizeof message, pos, " expected ");
6642|         pos = safecatn(message, sizeof message, pos, test_pixel.colour_type);
